import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"openshield fix — Auto-Repair","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/cli/fix.md","filePath":"openshield-xdp/cli/fix.md","lastUpdated":null}'),n={name:"openshield-xdp/cli/fix.md"};function o(d,e,l,r,p,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="openshield-fix-—-auto-repair" tabindex="-1"><code>openshield fix</code> — Auto-Repair <a class="header-anchor" href="#openshield-fix-—-auto-repair" aria-label="Permalink to &quot;\`openshield fix\` — Auto-Repair&quot;">​</a></h1><p>The <code>fix</code> command auto-detects and repairs 7 categories of common issues that can prevent OpenShield-XDP from loading.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fix</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # Standard mode — shows one line per fix</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fix</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Verbose mode — shows detail for each step</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fix</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Same as -v</span></span></code></pre></div><p>Root is required because <code>/sys/fs/bpf</code> and <code>/var/run</code> need write access.</p><h2 id="the-7-fixable-issues" tabindex="-1">The 7 fixable issues <a class="header-anchor" href="#the-7-fixable-issues" aria-label="Permalink to &quot;The 7 fixable issues&quot;">​</a></h2><h3 id="_1-stale-bpf-pins" tabindex="-1">1. Stale BPF pins <a class="header-anchor" href="#_1-stale-bpf-pins" aria-label="Permalink to &quot;1. Stale BPF pins&quot;">​</a></h3><p><strong>Problem:</strong> Previous installation or crash left pinned maps/programs in <code>/sys/fs/bpf/</code>. New load fails with &quot;reusing pinned map&quot; or &quot;parameter mismatch&quot; because the pinned map&#39;s struct layout differs from the current version.</p><p><strong>Fix:</strong> Removes known stale pin files:</p><ul><li><code>/sys/fs/bpf/config_map</code>, <code>/sys/fs/bpf/global_stats_map</code>, <code>/sys/fs/bpf/ip_stats_map</code></li><li><code>/sys/fs/bpf/ban_map</code>, <code>/sys/fs/bpf/whitelist_map</code>, <code>/sys/fs/bpf/baseline_map</code></li><li><code>/sys/fs/bpf/panic_bucket_map</code>, <code>/sys/fs/bpf/events_map</code>, <code>/sys/fs/bpf/prof_map</code></li><li><code>/sys/fs/bpf/l7_sig_map</code>, <code>/sys/fs/bpf/prefix_ban_map</code>, <code>/sys/fs/bpf/bloom_map</code></li><li><code>/sys/fs/bpf/xdp_prog</code></li><li>IPv6 variants: <code>whitelist_map_v6</code>, <code>ip_stats_map_v6</code>, <code>ban_map_v6</code>, <code>subnet_ban_map</code>, <code>subnet_ban_map_v6</code></li><li>Entire <code>/sys/fs/bpf/openshield</code> directory</li></ul><h3 id="_2-bpf-filesystem-permissions-mounting" tabindex="-1">2. BPF filesystem permissions/mounting <a class="header-anchor" href="#_2-bpf-filesystem-permissions-mounting" aria-label="Permalink to &quot;2. BPF filesystem permissions/mounting&quot;">​</a></h3><p><strong>Problem:</strong> <code>/sys/fs/bpf</code> is not mounted or not accessible. BPF programs require the BPF filesystem.</p><p><strong>Fix:</strong> If <code>/sys/fs/bpf</code> doesn&#39;t exist, mounts it with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bpf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bpf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/bpf</span></span></code></pre></div><h3 id="_3-stale-pid-file" tabindex="-1">3. Stale PID file <a class="header-anchor" href="#_3-stale-pid-file" aria-label="Permalink to &quot;3. Stale PID file&quot;">​</a></h3><p><strong>Problem:</strong> <code>/var/run/openshield/loader.pid</code> exists but the process with that PID is dead. <code>openshield load</code> sees the PID file and thinks a loader is already running.</p><p><strong>Fix:</strong> Reads the PID from the file, checks if <code>/proc/&lt;pid&gt;</code> exists:</p><ul><li>If the process is dead → removes the stale PID file</li><li>If the PID file is empty → removes it</li><li>If the process is alive → leaves it (not stale)</li></ul><h3 id="_4-stale-var-run-openshield-directory" tabindex="-1">4. Stale <code>/var/run/openshield</code> directory <a class="header-anchor" href="#_4-stale-var-run-openshield-directory" aria-label="Permalink to &quot;4. Stale \`/var/run/openshield\` directory&quot;">​</a></h3><p><strong>Problem:</strong> Socket files, lock files, or other artifacts left in <code>/var/run/openshield</code> from a previous run.</p><p><strong>Fix:</strong> Removes all entries in <code>/var/run/openshield</code> — but only if no loader is currently running (checks <code>isLoaderRunning()</code> first).</p><h3 id="_5-orphaned-xdp-programs" tabindex="-1">5. Orphaned XDP programs <a class="header-anchor" href="#_5-orphaned-xdp-programs" aria-label="Permalink to &quot;5. Orphaned XDP programs&quot;">​</a></h3><p><strong>Problem:</strong> XDP program is still attached to a NIC but no corresponding BPF pin file exists. This happens when the loader is killed with SIGKILL (no chance to clean up) or the system crashed.</p><p><strong>Fix:</strong> Two methods:</p><ol><li>Uses <code>bpftool link show -j</code> to find XDP links. If found, iterates common interface names (<code>eno1</code>, <code>eth0</code>, <code>ens3</code>) and runs <code>bpftool net detach xdp dev &lt;iface&gt;</code>.</li><li>Checks for orphaned <code>/sys/fs/bpf/xdp_prog</code> pin without a running loader — removes it.</li></ol><h3 id="_6-config-map-struct-mismatches" tabindex="-1">6. Config map struct mismatches <a class="header-anchor" href="#_6-config-map-struct-mismatches" aria-label="Permalink to &quot;6. Config map struct mismatches&quot;">​</a></h3><p><strong>Problem:</strong> Pinned <code>config_map</code> has a different struct layout than the current version (e.g., after an upgrade that added/removed fields). Loading fails with &quot;expected map size N, got M&quot;.</p><p><strong>Fix:</strong> Removes stale config maps at:</p><ul><li><code>/sys/fs/bpf/config_map</code></li><li><code>/sys/fs/bpf/openshield/config_map</code></li></ul><h3 id="_7-missing-required-directories" tabindex="-1">7. Missing required directories <a class="header-anchor" href="#_7-missing-required-directories" aria-label="Permalink to &quot;7. Missing required directories&quot;">​</a></h3><p><strong>Problem:</strong> Expected directories don&#39;t exist, causing file-creation failures.</p><p><strong>Fix:</strong> Creates (with <code>0755</code>):</p><ul><li><code>/etc/openshield</code> — config file</li><li><code>/var/lib/openshield/state</code> — persistent state</li><li><code>/var/lib/openshield/pins</code> — BPF pin backing</li><li><code>/var/log/openshield</code> — log output</li><li><code>/var/run/openshield</code> — runtime files</li></ul><h2 id="when-to-use-fix-vs-manual-intervention" tabindex="-1">When to use <code>fix</code> vs manual intervention <a class="header-anchor" href="#when-to-use-fix-vs-manual-intervention" aria-label="Permalink to &quot;When to use \`fix\` vs manual intervention&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th style="text-align:center;">Use <code>openshield fix</code></th><th>Manual intervention needed</th></tr></thead><tbody><tr><td>After a crash or SIGKILL</td><td style="text-align:center;">✅</td><td>—</td></tr><tr><td>After upgrading OpenShield</td><td style="text-align:center;">✅</td><td>Check config compatibility</td></tr><tr><td>&quot;reusing pinned map&quot; error</td><td style="text-align:center;">✅</td><td>—</td></tr><tr><td>&quot;parameter mismatch&quot; error</td><td style="text-align:center;">✅</td><td>—</td></tr><tr><td>&quot;device or resource busy&quot;</td><td style="text-align:center;">✅</td><td>—</td></tr><tr><td><code>/sys/fs/bpf</code> doesn&#39;t exist</td><td style="text-align:center;">✅</td><td>—</td></tr><tr><td>NIC driver doesn&#39;t support XDP</td><td style="text-align:center;">❌</td><td>Install a supported NIC/driver</td></tr><tr><td>Kernel too old (no BTF)</td><td style="text-align:center;">❌</td><td>Upgrade kernel or rebuild with <code>CONFIG_DEBUG_INFO_BTF=y</code></td></tr><tr><td>Config file is invalid YAML</td><td style="text-align:center;">❌</td><td>Fix <code>/etc/openshield/openshield.yaml</code></td></tr><tr><td>Disk full</td><td style="text-align:center;">❌</td><td>Free space on <code>/var</code> for logs</td></tr><tr><td>Permission denied on <code>bpftool</code></td><td style="text-align:center;">❌</td><td>Install <code>bpftool</code> or run as root</td></tr></tbody></table><h2 id="auto-invocation" tabindex="-1">Auto-invocation <a class="header-anchor" href="#auto-invocation" aria-label="Permalink to &quot;Auto-invocation&quot;">​</a></h2><p><code>openshield load</code> automatically runs <code>fix</code> internally when it encounters map-related errors (&quot;failed to create&quot;, &quot;parameter mismatch&quot;, &quot;reusing pinned map&quot;). You don&#39;t need to manually run <code>fix &amp;&amp; load</code> — just <code>load</code> handles it. However, explicitly running <code>fix</code> can be useful as a pre-flight check before loading.</p><h2 id="example-output" tabindex="-1">Example output <a class="header-anchor" href="#example-output" aria-label="Permalink to &quot;Example output&quot;">​</a></h2><h3 id="standard-mode" tabindex="-1">Standard mode <a class="header-anchor" href="#standard-mode" aria-label="Permalink to &quot;Standard mode&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpenShield-XDP — Automated Repair</span></span>
<span class="line"><span>==================================</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Clearing stale BPF pins ... fixed</span></span>
<span class="line"><span>  Fixing /sys/fs/bpf permissions ... ok</span></span>
<span class="line"><span>  Removing stale PID file ... ok</span></span>
<span class="line"><span>  Clearing /var/run/openshield ... fixed</span></span>
<span class="line"><span>  Detaching orphaned XDP programs ... ok</span></span>
<span class="line"><span>  Removing stale config maps ... fixed</span></span>
<span class="line"><span>  Creating required directories ... ok</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Issues checked: 7, Fixed: 3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>All issues resolved. Run &#39;openshield load&#39; to start.</span></span></code></pre></div><h3 id="verbose-mode" tabindex="-1">Verbose mode <a class="header-anchor" href="#verbose-mode" aria-label="Permalink to &quot;Verbose mode&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpenShield-XDP — Automated Repair</span></span>
<span class="line"><span>==================================</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Clearing stale BPF pins ...   removed: /sys/fs/bpf/config_map</span></span>
<span class="line"><span>  removed: /sys/fs/bpf/ban_map</span></span>
<span class="line"><span>  cleared: /sys/fs/bpf/openshield</span></span>
<span class="line"><span>fixed</span></span>
<span class="line"><span>  ...</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p><a href="/pingless-studios-docs/openshield-xdp/cli/load">Load Deep-Dive</a> · <a href="/pingless-studios-docs/openshield-xdp/cli/status">Status Output</a> · <a href="/pingless-studios-docs/openshield-xdp/cli/commands">CLI Commands</a></p>`,44)])])}const f=s(n,[["render",o]]);export{u as __pageData,f as default};
